extractor:
Array.from(document.querySelectorAll('article[data-id]')).slice(0, 20).map(article => {
  const permalink = article.querySelector('a.status__relative-time[href]');
  const href = permalink && permalink.getAttribute('href');
  const author = article.querySelector('.status__display-name .display-name__html');
  const content = article.querySelector('.status__content__text--visible');
  const time = permalink && permalink.querySelector('time[datetime]');
  return {
    sourceId: article.dataset.id || (href ? new URL(href, location.origin).pathname : null),
    url: href ? new URL(href, location.origin).href : null,
    author: author ? author.innerText.trim() || null : null,
    text: content ? content.innerText.trim() : '',
    createdAt: time ? time.dateTime || null : null
  };
}).filter(item => item.sourceId && item.url && item.text)
